const esc=s=>String(s??'').replace(/[&<>"']/g,a=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[a]));
const percent=(v,max)=>max?Math.round(v/max*100):0;
const labelDate=iso=>m.fromISO(iso).toLocaleDateString('tr-TR',{day:'numeric',month:'short'});
const range=w=>`${labelDate(w)} – ${labelDate(m.addDays(w,6))}`;
const curWeek=()=>m.weekStart(m.dayISO(new Date()));
const state=()=>c.state;
const course=id=>m.get(state(),'courses',id);
