// Unified editor: all structural operations stay in one outline; existing record IDs remain stable.
function openOutline(id){const r=resource(id||resourceId);if(!r)return toast('Önce kaynak seç.');outlineResourceId=r.id;outlineFolded.clear();$('#outlineTitle').textContent=r.title+' · İçindekiler';renderOutline();$('#outlineDialog').showModal()}
function outlineOptions(rid,excludeId=null){const banned=new Set(excludeId?[excludeId,...descendantIds(excludeId)]:[]);return [{value:'',label:'En üst düzey'},...m.nodes(state(),rid).filter(n=>!banned.has(n.id)).map(n=>({value:n.id,label:n.title}))]}
function renderOutline(){
 const rid=outlineResourceId;if(!rid)return;
 const s=state(),items=m.nodes(s,rid),leaves=m.leaves(s,rid);
 const validIds=new Set(items.map(n=>n.id));for(const key of [...outlineFolded])if(!validIds.has(key))outlineFolded.delete(key);
 const typeName=n=>n.type==='quiz'?'Alıştırma':n.type==='test'?'Test':n.type==='section'?'Alt bölüm':'Konu';
 function branch(parent,depth,trail){if(depth>80)return '';
  return m.children(s,parent,rid).filter(n=>!trail.has(n.id)).map(n=>{
   const children=m.children(s,n.id,rid),hasKids=children.length>0,folded=outlineFolded.has(n.id);
   const label=depth===0?'Ünite':hasKids||n.type==='section'?'Alt başlık':typeName(n);
   return `<div class="outline-branch" role="treeitem" aria-level="${depth+1}" aria-label="${esc(n.title)}" ${hasKids?`aria-expanded="${!folded}"`:''}>
    <div class="outline-row outline-level-${Math.min(depth,3)} ${hasKids?'outline-parent':'outline-leaf'}">
     ${hasKids?`<button class="outline-toggle" data-outline="toggle" data-id="${n.id}" aria-label="${esc(n.title)} ${folded?'genişlet':'daralt'}" aria-expanded="${!folded}">${folded?'▸':'▾'}</button>`:'<span class="outline-toggle-spacer" aria-hidden="true"></span>'}
     <span class="outline-type" aria-hidden="true">${depth===0?'▣':hasKids||n.type==='section'?'▫':n.type==='quiz'?'◇':n.type==='test'?'⬡':'○'}</span>
     <div class="outline-name"><strong>${esc(n.title)}</strong><small>${label}${hasKids?' · '+children.length+' alt öğe':''}</small></div>
     <button class="outline-more" data-outline="menu" data-id="${n.id}" aria-label="${esc(n.title)} işlemleri" aria-haspopup="true">•••</button>
    </div>
    ${hasKids&&!folded?`<div class="outline-children" role="group">${branch(n.id,depth+1,new Set([...trail,n.id]))}</div>`:''}
   </div>`}).join('');}
 $('#outlineCount').textContent=items.length+' başlık · '+leaves.length+' takip konusu';
 $('#outlineTree').innerHTML=branch(null,0,new Set())||'<p class="muted-text">Henüz başlık yok. Üst bölüm ekleyebilir veya AI ile kaynak içindekilerini aktarabilirsin.</p>';
}
function outlineNodeEditor(id=null,parentId=null){const r=resource(outlineResourceId),n=id?node(id):null;if(!r)return;const parent=n?n.parentId:parentId,opts=outlineOptions(r.id,id);const fields=[textField('title','Başlık',n?.title||''),optionField('type','İçerik türü',n?.type||'section',[{value:'section',label:'Bölüm / alt bölüm'},{value:'topic',label:'Konu'},{value:'quiz',label:'Alıştırma / quiz'},{value:'test',label:'Test'}]),optionField('parentId','Hangi başlığın altında?',parent||'',opts)];$('#outlineDialog').close();openEditor(n?'Başlığı düzenle':'Yeni başlık ekle',fields,v=>{if(!v.title.trim())throw Error('Başlık boş olamaz.');let destination=v.parentId||null;let children=id?descendantIds(id):[];if(id&&(destination===id||children.includes(destination)))throw Error('Bir bölüm kendi altına taşınamaz.');mutate(s=>{if(n){let live=m.get(s,'nodes',id);const moving=live.parentId!==destination;const newOrder=m.children(s,destination,r.id).filter(x=>x.id!==id).length;m.update(live,{title:v.title.trim(),type:v.type,parentId:destination,sortOrder:moving?newOrder:live.sortOrder})}else m.add(s,'nodes',{resourceId:r.id,parentId:destination,title:v.title.trim(),type:v.type,sortOrder:m.children(s,destination,r.id).length})});outlineResourceId=r.id;renderOutline()});outlineReturnPending=true}
function outlineAction(action,id){const rid=outlineResourceId;if(!rid)return;const n=id?node(id):null;if(action==='toggle'){outlineFolded.has(id)?outlineFolded.delete(id):outlineFolded.add(id);return renderOutline()}if(action==='menu'){const n=node(id);if(!n)return;const anchor=document.querySelector(`[data-outline="menu"][data-id="${id}"]`);let menu=$('#outlineContextMenu');if(!menu){menu=document.createElement('div');menu.id='outlineContextMenu';menu.className='outline-context-menu';menu.setAttribute('role','menu');document.body.appendChild(menu)}if(menu.dataset.nodeId===id&&!menu.hidden){menu.hidden=true;return}menu.dataset.nodeId=id;menu.innerHTML=`<button data-outline="edit" data-id="${id}">✎ Düzenle / başka başlık altına taşı</button><button data-outline="add-child" data-id="${id}">＋ Alt başlık veya konu ekle</button><button data-outline="up" data-id="${id}">↑ Yukarı taşı</button><button data-outline="down" data-id="${id}">↓ Aşağı taşı</button><button class="outline-danger" data-outline="delete" data-id="${id}">Sil</button>`;menu.hidden=false;const bounds=anchor.getBoundingClientRect();menu.style.top=Math.min(bounds.bottom+5,innerHeight-230)+'px';menu.style.left=Math.max(8,Math.min(bounds.right-210,innerWidth-226))+'px';return}if(action==='add-root')return outlineNodeEditor();if(action==='add-child')return outlineNodeEditor(null,id);if(action==='edit')return outlineNodeEditor(id);if(action==='import'){ $('#outlineDialog').close(); return importStart(rid) }if(!n)return;$('#outlineContextMenu')?.setAttribute('hidden','');if(action==='delete'){let ids=[id,...descendantIds(id)],completed=ids.filter(x=>m.status(state(),x)!=='notstarted').length,assigned=ids.filter(x=>m.liveAssignments(state()).some(a=>a.nodeId===x)).length;let msg=`“${n.title}” ve ${ids.length-1} alt başlığı silinsin mi? ${completed} ilerleme kaydı, ${assigned} aktif plan etkilenebilir. İşlem geri alınamaz; önce JSON yedeği indir.`;if(!confirm(msg))return;mutate(s=>{for(let nid of ids){let item=m.get(s,'nodes',nid);if(item)m.remove(s,'nodes',item);m.unassign(s,nid)}});return renderOutline()}if(action==='up'||action==='down'){let sib=m.children(state(),n.parentId,rid),ix=sib.findIndex(x=>x.id===id),swap=sib[ix+(action==='up'?-1:1)];if(!swap)return;mutate(s=>{let a=m.get(s,'nodes',id),b=m.get(s,'nodes',swap.id),order=a.sortOrder;m.update(a,{sortOrder:b.sortOrder});m.update(b,{sortOrder:order})});renderOutline()}}
function previewRender(){if(!pendingImport)return;$('#previewInfo').textContent=`Kaynağa erişim: ${pendingImport.source_access==='full'?'Tam':pendingImport.source_access==='partial'?'Kısmi':'Erişilemedi'} · ${pendingImport.notes.length?pendingImport.notes.join(' · '):'Başlıkların kaynakla eşleştiğini kontrol et.'} · Sıralama ve üst başlıkları içe aktarmadan önce denetle.`;
  const flattened=[];function paths(nodes,prefix='',depth=0){nodes.forEach((n,i)=>{n.__path=prefix+String(i);flattened.push({path:n.__path,title:n.title,depth});paths(n.children,n.__path+'.',depth+1)})}paths(pendingImport.structure);
  function branch(nodes){return nodes.map(n=>{const parentPath=n.__path.includes('.')?n.__path.slice(0,n.__path.lastIndexOf('.')):'';let options='<option value="">Üst düzey</option>'+flattened.filter(x=>x.path!==n.__path&&!x.path.startsWith(n.__path+'.')).map(x=>`<option value="${esc(x.path)}" ${parentPath===x.path?'selected':''}>${'— '.repeat(Math.min(x.depth,8))}${esc(x.title)}</option>`).join('');return `<div class="tree-branch"><div class="tree-entry"><input data-tree-title="${n.__path}" value="${esc(n.title)}" aria-label="Başlık"><button class="tiny-btn" data-tree="add" data-path="${n.__path}" title="Alt başlık ekle">＋</button><button class="tiny-btn" data-tree="up" data-path="${n.__path}" title="Yukarı">↑</button><button class="tiny-btn" data-tree="down" data-path="${n.__path}" title="Aşağı">↓</button><button class="tiny-btn" data-tree="delete" data-path="${n.__path}">Sil</button></div><label class="tree-parent-label">Hangi başlığın altında?<select data-tree-parent="${n.__path}" aria-label="${esc(n.title)} üst başlık">${options}</select></label>${branch(n.children)}</div>`}).join('')}
  $('#importTree').innerHTML=branch(pendingImport.structure)||'<p class="muted-text">Boş kaynak haritası.</p>'}
function previewReparent(path,target){if(!pendingImport)return;const origin=pathLocation(path);if(target&&(target===path||target.startsWith(path+'.')))throw Error('Bir başlık kendi altına taşınamaz.');const dest=target?pathLocation(target).node:null;const moving=origin.node;origin.list.splice(origin.index,1);(dest?dest.children:pendingImport.structure).push(moving);previewRender()}
function pathLocation(path){let parts=String(path).split('.').map(Number),arr=pendingImport.structure,parent=null;for(const i of parts){if(!arr[i])throw Error('Başlık bulunamadı.');parent=arr[i];if(i!==parts[parts.length-1]){}arr=parent.children}let index=parts.pop(),list=pendingImport.structure;for(let i of parts)list=list[i].children;return {list,index,node:list[index]}}
function treeAction(act,path){let {list,index,node}=pathLocation(path);if(act==='delete')list.splice(index,1);if(act==='add')node.children.push({title:'Yeni alt başlık',children:[]});if(act==='up'&&index>0)[list[index-1],list[index]]=[list[index],list[index-1]];if(act==='down'&&index<list.length-1)[list[index],list[index+1]]=[list[index+1],list[index]];previewRender()}
function reviewAction(act,id){let current=m.get(state(),'reviews',id);if(!current)return;let ids=$$('[data-review-item]:checked').map(x=>x.dataset.reviewItem);if(act==='review-move'&&!ids.length){toast('En az bir konu seç.');return}mutate(s=>{let r=m.get(s,'reviews',id);if(act==='review-move'){let w=$('#reviewTarget').value;for(const nid of ids)if(node(nid))m.assign(s,nid,w)}if(act==='review-unassign')for(const nid of ids)if(node(nid))m.unassign(s,nid);if(act!=='review-defer')m.update(r,{status:'handled',reviewedAt:m.now()});else m.update(r,{status:'deferred',reviewedAt:null})});toast(act==='review-defer'?'Değerlendirme ertelendi.':'Değerlendirme kaydedildi.')}
